CREATE PROCEDURE sp_export_CT_Employee_036_file AS /** ## Procedure Name       *[toast].[dbo].[sp_export_CT_Employee_036_file]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20250221   **Report Name**         *IT ONLY - Crunchtime 036 Employee File*   **Summary**   *summary of report*      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;          		declare @Params varchar(2000) = (select Params = '' for json path)                  create table #Results          ( EmployeeGUID varchar(50) default '', Employee_Number varchar(40) default '', Payroll_ID_Number varchar(20) default '', POS_ID varchar(40) default '', Primary_Location_Code varchar(6) default '', Status varchar(10) default '', Date_Hired varchar(10) default '', Date_Terminated varchar(10) default '', Termination_Reason_Code varchar(10) default '', Eligible_for_Rehire_Flag char(1) default '', First_Name varchar(40), Middle_Name varchar(40) default '', Last_Name varchar(40), Manager_Flag char(1) default '', Sex char(1) default '', Ethnic_Group_Code varchar(10) default '', Phone_Number varchar(30) default '', Broadcast_Schedule_Flag char(1) default '', Email_Address varchar(75) default '', Emergency_Contact_Name varchar(40) default '', Emergency_Contact_Number varchar(30) default '', Nickname varchar(20) default '', Allergies varchar(25) default '', Union_Code varchar(10) default '', Minor_Labor_Program_Code varchar(10) default '', Address_1 varchar(30) default '', Address_2 varchar(30) default '', City varchar(40) default '', StateProvince varchar(3) default '', Postal_Code varchar(10) default '', Country varchar(35) default '', Social_Security_Number varchar(20) default '', SUISDI_Tax_Jurisdiction_Code varchar(6) default '', Pay_Type varchar(20) default '', State_Marital_Status_Code varchar(10) default '', State_Exemptions varchar(3) default '', State_Additional_Withholding varchar(10) default '', Uniform_Deduction_Amount varchar(10) default '', Date_of_Birth varchar(10) default '', Salary_Amount varchar(30) default '', Federal_Marital_Status_Code varchar(10) default '', Federal_Exemptions varchar(3) default '', Federal_Additional_Withholding varchar(10) default '', Meal_Program_Deduction varchar(10) default '', Position_Code_1 varchar(10) default '', Position_Code_2 varchar(10) default '', Position_Code_3 varchar(10) default '', Position_Code_4 varchar(10) default '', Position_Code_5 varchar(10) default '', Position_Code_6 varchar(10) default '', Position_Code_7 varchar(10) default '', Position_Code_8 varchar(10) default '', Position_Code_9 varchar(10) default '', Position_Code_10 varchar(10) default '', Pay_Rate_1 varchar(30) default '', Pay_Rate_2 varchar(30) default '', Pay_Rate_3 varchar(30) default '', Pay_Rate_4 varchar(30) default '', Pay_Rate_5 varchar(30) default '', Pay_Rate_6 varchar(30) default '', Pay_Rate_7 varchar(30) default '', Pay_Rate_8 varchar(30) default '', Pay_Rate_9 varchar(30) default '', Pay_Rate_10 varchar(30) default '', Skill_Level_1 varchar(3) default '', Skill_Level_2 varchar(3) default '', Skill_Level_3 varchar(3) default '', Skill_Level_4 varchar(3) default '', Skill_Level_5 varchar(3) default '', Skill_Level_6 varchar(3) default '', Skill_Level_7 varchar(3) default '', Skill_Level_8 varchar(3) default '', Skill_Level_9 varchar(3) default '', Skill_Level_10 varchar(3) default '', Employee_Checklist_Item_1 varchar(40) default '', Employee_Checklist_Item_2 varchar(40) default '', Employee_Checklist_Item_3 varchar(40) default '', Employee_Checklist_Item_4 varchar(40) default '', Employee_Checklist_Item_5 varchar(40) default '', Employee_Checklist_Item_6 varchar(40) default '', Employee_Checklist_Item_7 varchar(40) default '', Employee_Checklist_Item_8 varchar(40) default '', Employee_Checklist_Item_9 varchar(40) default '', Employee_Checklist_Item_10 varchar(40) default '', Wage_Matrix_Row_1 varchar(3) default '', Wage_Matrix_Row_2 varchar(3) default '', Wage_Matrix_Row_3 varchar(3) default '', Wage_Matrix_Row_4 varchar(3) default '', Wage_Matrix_Row_5 varchar(3) default '', Wage_Matrix_Row_6 varchar(3) default '', Wage_Matrix_Row_7 varchar(3) default '', Wage_Matrix_Row_8 varchar(3) default '', Wage_Matrix_Row_9 varchar(3) default '', Wage_Matrix_Row_10 varchar(3) default '', Flex_Field_1 varchar(30) default '', Flex_Field_2 varchar(30) default '', Flex_Field_3 varchar(30) default '', Flex_Field_4 varchar(30) default '', Flex_Field_5 varchar(30) default '', Flex_Field_6 varchar(30) default '', Flex_Field_7 varchar(30) default '', Flex_Field_8 varchar(30) default '', Flex_Field_9 varchar(30) default '', Flex_Field_10 varchar(30) default '', Break_Waiver char(1) default '', Part_time_flag char(1) default '', Sick_leave_Hours_Available varchar(30) default '', PTO_Field_1 varchar(30) default '', PTO_Field_2 varchar(30) default '', PTO_Field_3 varchar(30) default '', PTO_Field_4 varchar(30) default '', PTO_Field_5 varchar(30) default '', PTO_Field_6 varchar(30) default '', PTO_Field_7 varchar(30) default '', PTO_Field_8 varchar(30) default '', PTO_Field_9 varchar(30) default '', PTO_Field_10 varchar(30)default '' )          insert into #Results(EmployeeGUID, Employee_Number, Payroll_ID_Number, Primary_Location_Code, Status, Date_Hired, Date_Terminated, Termination_Reason_Code, First_Name, Middle_Name, Last_Name, Phone_Number, Email_Address, Nickname, Date_of_Birth)         select distinct                e.GUID             ,  e.ExternalEmployeeId 'Employee_Number'             , e.ExternalEmployeeId 'Payroll_ID_Number'             , r.StoreID 'Primary_Location_Code'             , case                 when e.deleted = 1 then 'Terminated'                 else 'Active'               end as 'Status'             , convert(varchar(50),e.CreatedDate,101) 'Date_Hired'             , case                 when e.deleted = 1 then convert(varchar(50),e.DeletedDate,101)                 else ''               end as 'Date_Terminated'             , '' as 'Termination_Reason_Code'             , left(e.First, 40) as 'First_Name'             , '' as 'Middle_Name'             , left(e.Last, 40) as 'Last_Name'             , e.Phone as 'Phone Number'             , e.Email as 'Email_Address'             , left(e.ChosenName, 20) as 'Nickname' 			, convert(varchar(50),e.CreatedDate,101)         from toast.dbo.Employees e         join toast.dbo.restaurants r         on e.StoreGUID = r.GUID          select              r.StoreID             , e.GUID 'EmployeeGUID'             , jc.GUID 'JobGUID'             , jc.Code             , jc.DefaultWage 'Wage'             , jc.WageFrequency             , ROW_NUMBER() over (partition by r.StoreID, e.GUID order by r.StoreID, e.GUID) rownum         into #Jobs         from toast.dbo.EmployeeJobsByStore ejs         join toast.dbo.Employees e         on ejs.StoreGUID = e.StoreGUID         and ejs.EmployeeGUID = e.GUID         join toast.dbo.restaurants r         on e.StoreGUID = r.GUID         join toast.dbo.JobCodes jc         on ejs.JobCodeGUID = jc.GUID          update #Jobs set             Wage = ewj.Wage         from #jobs j         join restaurants r         on j.StoreID = r.StoreID         join EmployeeWagesByJob ewj         on r.GUID = ewj.StoreGUID         and j.EmployeeGUID = ewj.EmployeeGUID         and j.JobGUID = ewj.JobCodeGUID          update #Results set             Pay_Type = j.WageFrequency,             Position_Code_1 = j.Code,             Pay_Rate_1 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 1          update #Results set             Position_Code_2 = j.Code,             Pay_Rate_2 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 2          update #Results set             Position_Code_3 = j.Code,             Pay_Rate_3 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 3          update #Results set             Position_Code_4 = j.Code,             Pay_Rate_4 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 4          update #Results set             Position_Code_5 = j.Code,             Pay_Rate_5 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 5          update #Results set             Position_Code_6 = j.Code,             Pay_Rate_6 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 6          update #Results set             Position_Code_7 = j.Code,             Pay_Rate_7 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 7          update #Results set             Position_Code_8 = j.Code,             Pay_Rate_8 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 8          update #Results set             Position_Code_9 = j.Code,             Pay_Rate_9 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 9          update #Results set             Position_Code_10 = j.Code,             Pay_Rate_10 = isnull(Wage, 0)         from #Results r         join #Jobs j         on r.Primary_Location_Code = j.StoreID         and r.EmployeeGUID = j.EmployeeGUID         where j.rownum = 10          select 'CDPUSER' as 'User', convert(varchar,getdate(),101) as 'Date',             Employee_Number, Payroll_ID_Number, isnull(POS_ID, '') POS_ID, Primary_Location_Code, Status, Date_Hired, Date_Terminated, Termination_Reason_Code, isnull(Eligible_for_Rehire_Flag, '') Eligible_for_Rehire_Flag, First_Name, Middle_Name, Last_Name, isnull(Manager_Flag, '') Manager_Flag, isnull(Sex, '') Sex, isnull(Ethnic_Group_Code, '') Ethnic_Group_Code, Phone_Number, isnull(Broadcast_Schedule_Flag, '') Broadcast_Schedule_Flag, Email_Address, Emergency_Contact_Name, Emergency_Contact_Number, Nickname, Allergies, Union_Code, Minor_Labor_Program_Code, Address_1, Address_2, City, StateProvince, Postal_Code, Country, Social_Security_Number, SUISDI_Tax_Jurisdiction_Code, Pay_Type, State_Marital_Status_Code, State_Exemptions, State_Additional_Withholding, Uniform_Deduction_Amount, Date_of_Birth, Salary_Amount, Federal_Marital_Status_Code, Federal_Exemptions, Federal_Additional_Withholding, Meal_Program_Deduction, Position_Code_1, Position_Code_2, Position_Code_3, Position_Code_4, Position_Code_5, Position_Code_6, Position_Code_7, Position_Code_8, Position_Code_9, Position_Code_10, Pay_Rate_1, Pay_Rate_2, Pay_Rate_3, Pay_Rate_4, Pay_Rate_5, Pay_Rate_6, Pay_Rate_7, Pay_Rate_8, Pay_Rate_9, Pay_Rate_10, Skill_Level_1, Skill_Level_2, Skill_Level_3, Skill_Level_4, Skill_Level_5, Skill_Level_6, Skill_Level_7, Skill_Level_8, Skill_Level_9, Skill_Level_10, Employee_Checklist_Item_1, Employee_Checklist_Item_2, Employee_Checklist_Item_3, Employee_Checklist_Item_4, Employee_Checklist_Item_5, Employee_Checklist_Item_6, Employee_Checklist_Item_7, Employee_Checklist_Item_8, Employee_Checklist_Item_9, Employee_Checklist_Item_10, Wage_Matrix_Row_1, Wage_Matrix_Row_2, Wage_Matrix_Row_3, Wage_Matrix_Row_4, Wage_Matrix_Row_5, Wage_Matrix_Row_6, Wage_Matrix_Row_7, Wage_Matrix_Row_8, Wage_Matrix_Row_9, Wage_Matrix_Row_10, Flex_Field_1, Flex_Field_2, Flex_Field_3, Flex_Field_4, Flex_Field_5, Flex_Field_6, Flex_Field_7, Flex_Field_8, Flex_Field_9, Flex_Field_10, Break_Waiver, Part_time_flag, Sick_leave_Hours_Available, PTO_Field_1, PTO_Field_2, PTO_Field_3, PTO_Field_4, PTO_Field_5, PTO_Field_6, PTO_Field_7, PTO_Field_8, PTO_Field_9, PTO_Field_10         from #Results 		where Pay_Type = 'HOURLY' 		and Employee_Number != ''         order by Primary_Location_Code, Last_Name, First_Name          drop table #Results         drop table #Jobs                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName 			,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine 			,@Params = @Params;         THROW;     END CATCH END